1	package server
2	
3	import (
4		"encoding/json"
5		"fmt"
6		"net/http"
7		"sort"
8	)
9	
10	// Error code reported when the reconcile request envelope is structurally
11	// invalid: the body is not an object, names an unknown field, or carries an
12	// illegal expectedRevision.
13	const codeInvalidReconcileRequest = "invalid_reconcile_request"
14	
15	// reconcileResponse is the POST /v1/state/reconcile payload. State and
16	// Revision always report the file contents the run reconciled against: the
17	// endpoint never writes and never bumps the revision. CurrentRevision is set
18	// only on an expectedRevision conflict.
19	type reconcileResponse struct {
20		Valid           bool              `json:"valid"`
21		Errors          []validationError `json:"errors"`
22		Applied         *[]planChange     `json:"applied,omitempty"`
23		Summary         planSummary       `json:"summary"`
24		State           *stateDocument    `json:"state,omitempty"`
25		Revision        *int64            `json:"revision,omitempty"`
26		CurrentRevision *int64            `json:"currentRevision,omitempty"`
27	}
28	
29	// handleReconcile serves POST /v1/state/reconcile: it converges the remote
30	// toward the stored state without persisting anything. The run observes every
31	// saved resource in ascending address order, classifies each as create,
32	// update, or noop against the saved snapshot, and then applies the changes in
33	// the saved state's deterministic topological order. It never writes the
34	// state file and never bumps the revision.
35	func (b *stateBackend) handleReconcile(source providerSource) http.HandlerFunc {
36		return func(w http.ResponseWriter, r *http.Request) {
37			w.Header().Set("Content-Type", "application/json; charset=utf-8")
38			if r.Method != http.MethodPost {
39				rejectMethodNotAllowed(w)
40				return
41			}
42	
43			doc, ok := decodeConfigurationBody(w, r)
44			if !ok {
45				return
46			}
47			expectedRevision, ok := checkReconcileEnvelope(w, doc)
48			if !ok {
49				return
50			}
51	
52			// The Observer capability check the mode runs before locking or I/O,
53			// exactly like drift detection.
54			if !source.checkObserverPreLock(w, "reconciliation requires the provider to implement Observer") {
55				return
56			}
57	
58			// One lock spans the read, every observation, and every Apply call;
59			// every outcome below releases it via the deferred unlock.
60			unlock, acquired := tryLockState(b.path)
61			if !acquired {
62				writeValidation(w, http.StatusConflict, []validationError{{
63					Code:    codeStateLocked,
64					Message: "state file is locked by another state run",
65					Path:    "",
66				}})
67				return
68			}
69			defer unlock()
70	
71			current, err := readStateFile(b.path)
72			if err != nil {
73				writeValidation(w, http.StatusInternalServerError, []validationError{{
74					Code:    codeStateReadError,
75					Message: "state file cannot be read or does not hold a valid state document",
76					Path:    "",
77				}})
78				return
79			}
80	
81			if expectedRevision != nil && *expectedRevision != current.revision {
82				currentRevision := current.revision
83				w.WriteHeader(http.StatusConflict)
84				_ = json.NewEncoder(w).Encode(reconcileResponse{
85					Valid: false,
86					Errors: []validationError{{
87						Code:    codeStateConflict,
88						Message: "expectedRevision does not match the current state revision",
89						Path:    "/expectedRevision",
90					}},
91					CurrentRevision: &currentRevision,
92				})
93				return
94			}
95	
96			// Observe in ascending address order; that order indexes observation
97			// errors. The saved snapshot is the before of an update and the after
98			// of every create/update.
99			observed := make([]planResource, len(current.resources))
100			copy(observed, current.resources)
101			sort.Slice(observed, func(i, j int) bool { return observed[i].address < observed[j].address })
102	
103			// Precheck: every saved resource must route to a Provider
104			// implementing Observer before anything is observed or applied. Any
105			// failure aborts the run without calling Observe or Apply and
106			// without writing state.
107			observers := make([]Observer, len(observed))
108			for i, resource := range observed {
109				observer, precheckErr := source.observerFor(resource, i)
110				if precheckErr != nil {
111					writeValidation(w, http.StatusServiceUnavailable, []validationError{*precheckErr})
112					return
113				}
114				observers[i] = observer
115			}
116	
117			changes := []planChange{}
118			var summary planSummary
119			for i, resource := range observed {
120				snapshot, observeErr := observers[i].Observe(r.Context(), resource.address)
121				if observeErr != nil {
122					// Stop before any change is made: nothing has been applied yet.
123					writeValidation(w, http.StatusBadGateway, []validationError{{
124						Code:    codeObserverError,
125						Message: observeErr.Error(),
126						Path:    fmt.Sprintf("/resources/%d", i),
127					}})
128					return
129				}
130	
131				saved := snapshotOf(resource)
132				if snapshot == nil {
133					// The resource is saved but absent remotely: recreate it.
134					summary.Create++
135					after := saved
136					changes = append(changes, planChange{Address: resource.address, Action: "create", After: &after})
137					continue
138				}
139	
140				normalized, normalizeErr := normalizeObserved(snapshot)
141				if normalizeErr != nil {
142					writeValidation(w, http.StatusBadGateway, []validationError{{
143						Code:    codeObserverInvalidResult,
144						Message: normalizeErr.Error(),
145						Path:    fmt.Sprintf("/resources/%d", i),
146					}})
147					return
148				}
149	
150				if snapshotsEquivalent(saved, normalized) {
151					summary.Noop++
152					continue
153				}
154				summary.Update++
155				before := normalized
156				after := saved
157				changes = append(changes, planChange{
158					Address: resource.address,
159					Action:  "update",
160					Before:  &before,
161					After:   &after,
162				})
163			}
164	
165			state := renderState(seedState(current.resources))
166			revision := current.revision
167	
168			// Reorder the observed changes into the saved state's deterministic
169			// topological order, so dependencies are converged first. Resources not
170			// in that order (none expected from a validated file) sort last.
171			changes = orderReconcileChanges(changes, current.order)
172	
173			// All noops: no Provider is ever invoked and the run succeeds even
174			// when none is registered.
175			applied := []planChange{}
176			if len(changes) > 0 {
177				// Every change's type was already prechecked against the
178				// registry above, so resolution cannot fail here; the check is
179				// kept as a defensive guard mirroring the apply endpoints.
180				providers := make([]Provider, len(changes))
181				for i, change := range changes {
182					typ := changeType(change)
183					provider, registered := source.providerFor(typ)
184					if !registered {
185						w.WriteHeader(http.StatusServiceUnavailable)
186						_ = json.NewEncoder(w).Encode(reconcileResponse{
187							Valid:    false,
188							Errors:   []validationError{source.applyUnavailable(typ, i)},
189							Summary:  summary,
190							State:    state,
191							Revision: &revision,
192						})
193						return
194					}
195					providers[i] = provider
196				}
197	
198				for i, change := range changes {
199					req := ChangeRequest{
200						Context: r.Context(),
201						Action:  change.Action,
202						Address: change.Address,
203						Before:  change.Before,
204						After:   change.After,
205					}
206					if err := providers[i].Apply(req); err != nil {
207						// Stop immediately without rolling back; successful
208						// changes and the full summary are still reported.
209						w.WriteHeader(http.StatusBadGateway)
210						_ = json.NewEncoder(w).Encode(reconcileResponse{
211							Valid:    false,
212							Errors:   []validationError{{Code: codeProviderError, Message: err.Error(), Path: fmt.Sprintf("/changes/%d", i)}},
213							Applied:  &applied,
214							Summary:  summary,
215							State:    state,
216							Revision: &revision,
217						})
218						return
219					}
220					applied = append(applied, change)
221				}
222			}
223	
224			w.WriteHeader(http.StatusOK)
225			_ = json.NewEncoder(w).Encode(reconcileResponse{
226				Valid:    true,
227				Errors:   []validationError{},
228				Applied:  &applied,
229				Summary:  summary,
230				State:    state,
231				Revision: &revision,
232			})
233		}
234	}
