236	// orderReconcileChanges re-expresses changes (observed in address order) in
237	// the saved state's topological order. The change set covers a subset of the
238	// saved addresses, so walking order and selecting by address yields the
239	// dependency-first execution order; any unmatched addresses follow in address
240	// order as a defensive fallback.
241	func orderReconcileChanges(changes []planChange, order []string) []planChange {
242		byAddress := make(map[string]planChange, len(changes))
243		for _, change := range changes {
244			byAddress[change.Address] = change
245		}
246		ordered := make([]planChange, 0, len(changes))
247		for _, address := range order {
248			if change, ok := byAddress[address]; ok {
249				ordered = append(ordered, change)
250				delete(byAddress, address)
251			}
252		}
253		if len(byAddress) != 0 {
254			remaining := make([]string, 0, len(byAddress))
255			for address := range byAddress {
256				remaining = append(remaining, address)
257			}
258			sort.Strings(remaining)
259			for _, address := range remaining {
260				ordered = append(ordered, byAddress[address])
261			}
262		}
263		return ordered
264	}
