266	// checkReconcileEnvelope validates the reconcile request: a JSON object that
267	// may hold only an optional expectedRevision, which must be a non-negative
268	// integer. On failure it writes the 422 invalid_reconcile_request response
269	// and returns ok=false.
270	func checkReconcileEnvelope(w http.ResponseWriter, doc any) (expectedRevision *int64, ok bool) {
