272		add := func(code, message, path string) {
273			errs = append(errs, validationError{Code: code, Message: message, Path: path})
274		}
275	
276		root, isObject := doc.(map[string]any)
277		if !isObject {
278			add(codeInvalidReconcileRequest, "request body must be a JSON object", "")
279		} else {
280			for key := range root {
281				if key != "expectedRevision" {
282					add(codeInvalidReconcileRequest, fmt.Sprintf("unknown field %q", key), "/"+pointerEscape(key))
283				}
284			}
285			if revRaw, has := root["expectedRevision"]; has {
286				if revision, valid := nonNegativeInt64(revRaw); valid {
287					expectedRevision = &revision
288				} else {
289					add(codeInvalidReconcileRequest, `"expectedRevision" must be a non-negative integer`, "/expectedRevision")
290				}
291			}
292		}
293	
294		if len(errs) != 0 {
