	  {"address": "a", "type": "net", "properties": {"cidr": "10.0.0.0/8", "n": 1}},
	  {"address": "b", "type": "vm", "properties": {"size": 1}, "dependsOn": ["a"]}
	]`
	writeDriftStateFile(t, path, 4, original)
