func TestApplyRetryDoesNotAdvanceToLaterChanges(t *testing.T) {
	body := planBody(`[`+resEntry("a", `[]`)+`,`+resEntry("b", `[]`)+`]`, `[]`)
	provider := &scriptedRetryProvider{failures: map[string]map[int]error{
		"a": {1: &retryableErr{msg: "t", retryable: true}},
