		t.Fatalf("error = %+v, want r3 at /changes/0", e)
	}
	if got := attemptsFor(provider.callsLocked(), "c"); fmt.Sprint(got) != "[1 2 3]" {
		t.Fatalf("attempts = %v, want [1 2 3]", got)
